mapper.select:
SELECT u.id, u.user_name, u.real_name, u.phone, u.role_code, u.audit_status, u.user_status, u.department_id, u.position_id, u.create_time, u.update_time FROM sys_user u LEFT JOIN employee_profile p ON p.user_id = u.id WHERE u.audit_status = 'APPROVED'
AND (LOCATE(#{keyword}, u.user_name) > 0 OR LOCATE(#{keyword}, u.real_name) > 0 OR LOCATE(#{keyword}, u.phone) > 0)
AND u.department_id = #{departmentId}
AND COALESCE(p.employment_status, 'ACTIVE') = #{employmentStatus}
ORDER BY u.create_time DESC, u.id DESC
